namespace Techies.Web.Domain;

// The five statuses shared with the Android app and backend (BRD §3).
public enum OrderStatus { AwaitingPayment, Confirmed, Completed, Cancelled, Failed }

public enum PaymentMethod { Cod, MockCard }

public enum PaymentStatus { Pending, Paid, Declined, Refunded }

public sealed class Order
{
    public Guid Id { get; set; } = Guid.CreateVersion7();
    // Generated by the database (order_ref_seq); null until the order is saved.
    public string OrderRef { get; set; } = null!;
    public Guid UserId { get; set; }
    public User User { get; set; } = null!;
    public OrderStatus Status { get; set; }
    public string? FailureCode { get; set; }

    public decimal Subtotal { get; set; }
    public decimal ShippingFee { get; set; }
    public string? CouponCode { get; set; }
    public decimal Discount { get; set; }
    public decimal Total { get; set; }

    // Shipping address snapshot: editing an address later must not rewrite past orders.
    public string ShipRecipient { get; set; } = "";
    public string ShipPhone { get; set; } = "";
    public string ShipLine1 { get; set; } = "";
    public string ShipWard { get; set; } = "";
    public string ShipDistrict { get; set; } = "";
    public string ShipProvince { get; set; } = "";

    public PaymentMethod PaymentMethod { get; set; }
    public PaymentStatus PaymentStatus { get; set; }

    public DateTimeOffset CreatedAt { get; set; }
    public DateTimeOffset UpdatedAt { get; set; }
    public DateTimeOffset? CompletedAt { get; set; }

    public List<OrderItem> Items { get; set; } = [];
}

public sealed class OrderItem
{
    public Guid Id { get; set; } = Guid.CreateVersion7();
    public Guid OrderId { get; set; }
    public Guid ProductId { get; set; }
    // Name, price and image are snapshots taken at checkout, not live catalog reads.
    public string ProductName { get; set; } = "";
    public decimal UnitPrice { get; set; }
    public string? ThumbnailUrl { get; set; }
    public int Quantity { get; set; }
    public decimal LineTotal { get; set; }
}

public enum CouponRedemptionStatus { Applied, Restored }

public sealed class CouponRedemption
{
    public Guid Id { get; set; } = Guid.CreateVersion7();
    public Guid CouponId { get; set; }
    public Guid OrderId { get; set; }
    public Guid CustomerId { get; set; }
    public decimal DiscountAmount { get; set; }
    public CouponRedemptionStatus Status { get; set; } = CouponRedemptionStatus.Applied;
    public DateTimeOffset RedeemedAt { get; set; }
    public DateTimeOffset? RestoredAt { get; set; }
}

public enum PointTransactionType { Earn, Redeem }

// Ledger of loyalty point changes: EARN when an order completes, REDEEM for a gift.
public sealed class PointTransaction
{
    public Guid Id { get; set; } = Guid.CreateVersion7();
    public Guid CustomerId { get; set; }
    public PointTransactionType TransactionType { get; set; }
    public long PointsDelta { get; set; }
    public Guid? OrderId { get; set; }
    public Guid? GiftRedemptionId { get; set; }
    public string? Note { get; set; }
    public DateTimeOffset CreatedAt { get; set; }
}
